<script setup lang="ts">
import { computed, ref, useTemplateRef, watch } from 'vue'

interface BorderGlowProps {
    className?: string
    edgeSensitivity?: number
    glowColor?: string
    backgroundColor?: string
    borderRadius?: number | string
    glowRadius?: number
    glowIntensity?: number
    coneSpread?: number
    animated?: boolean
    colors?: string[]
    fillOpacity?: number
    cardShadow?: string
    /** Set true when a parent overflow:hidden clips anything outside the card — skips the outer glow span */
    disableOuterGlow?: boolean
}

function parseHSL(hslStr: string): { h: number; s: number; l: number } {
    const match = hslStr.match(/([\d.]+)\s*([\d.]+)%?\s*([\d.]+)%?/)
    if (!match) return { h: 171, s: 85, l: 45 }
    return { h: parseFloat(match[1]), s: parseFloat(match[2]), l: parseFloat(match[3]) }
}

function buildBoxShadow(glowColor: string, intensity: number): string {
    const { h, s, l } = parseHSL(glowColor)
    const base = `${h}deg ${s}% ${l}%`
    const layers: [number, number, number, number, number, boolean][] = [
        [0, 0, 0, 1, 100, true],
        [0, 0, 1, 0, 60, true],
        [0, 0, 3, 0, 50, true],
        [0, 0, 6, 0, 40, true],
        [0, 0, 15, 0, 30, true],
        [0, 0, 25, 2, 20, true],
        [0, 0, 50, 2, 10, true],
        [0, 0, 1, 0, 60, false],
        [0, 0, 3, 0, 50, false],
        [0, 0, 6, 0, 40, false],
        [0, 0, 15, 0, 30, false],
        [0, 0, 25, 2, 20, false],
        [0, 0, 50, 2, 10, false],
    ]
    return layers
        .map(([x, y, blur, spread, alpha, inset]) => {
            const a = Math.min(alpha * intensity, 100)
            return `${inset ? 'inset ' : ''}${x}px ${y}px ${blur}px ${spread}px hsl(${base} / ${a}%)`
        })
        .join(', ')
}

function easeOutCubic(x: number) {
    return 1 - Math.pow(1 - x, 3)
}
function easeInCubic(x: number) {
    return x * x * x
}

interface AnimateOpts {
    start?: number
    end?: number
    duration?: number
    delay?: number
    ease?: (t: number) => number
    onUpdate: (v: number) => void
    onEnd?: () => void
}

function animateValue({
    start = 0,
    end = 100,
    duration = 1000,
    delay = 0,
    ease = easeOutCubic,
    onUpdate,
    onEnd,
}: AnimateOpts) {
    const t0 = performance.now() + delay
    function tick() {
        const elapsed = performance.now() - t0
        const t = Math.min(elapsed / duration, 1)
        onUpdate(start + (end - start) * ease(t))
        if (t < 1) requestAnimationFrame(tick)
        else if (onEnd) onEnd()
    }
    setTimeout(() => requestAnimationFrame(tick), delay)
}

const GRADIENT_POSITIONS = ['80% 55%', '69% 34%', '8% 6%', '41% 38%', '86% 85%', '82% 18%', '51% 4%']
const COLOR_MAP = [0, 1, 2, 0, 1, 2, 1]

function buildMeshGradients(colors: string[]): string[] {
    const gradients: string[] = []
    for (let i = 0; i < 7; i++) {
        const c = colors[Math.min(COLOR_MAP[i], colors.length - 1)]
        gradients.push(`radial-gradient(at ${GRADIENT_POSITIONS[i]}, ${c} 0px, transparent 50%)`)
    }
    gradients.push(`linear-gradient(${colors[0]} 0 100%)`)
    return gradients
}

const props = withDefaults(defineProps<BorderGlowProps>(), {
    className: '',
    edgeSensitivity: 30,
    glowColor: '171 85 45',
    backgroundColor: '#060010',
    borderRadius: 28,
    glowRadius: 40,
    glowIntensity: 1.0,
    coneSpread: 25,
    animated: false,
    colors: () => ['#54f4d4', '#21e0c0', '#08b89d'],
    fillOpacity: 0.5,
    cardShadow: '0 2px 8px var(--color-secondary-200, #e2e8f0), 0 1px 3px var(--color-secondary-300, #cbd5e1)',
    disableOuterGlow: false,
})

const cardRef = useTemplateRef<HTMLDivElement>('cardRef')
const isHovered = ref(false)
const cursorAngle = ref(45)
const edgeProximity = ref(0)
const sweepActive = ref(false)

const getCenterOfElement = (el: HTMLElement) => {
    const { width, height } = el.getBoundingClientRect()
    return [width / 2, height / 2]
}

const getEdgeProximity = (el: HTMLElement, x: number, y: number) => {
    const [cx, cy] = getCenterOfElement(el)
    const dx = x - cx
    const dy = y - cy
    let kx = Infinity
    let ky = Infinity
    if (dx !== 0) kx = cx / Math.abs(dx)
    if (dy !== 0) ky = cy / Math.abs(dy)
    return Math.min(Math.max(1 / Math.min(kx, ky), 0), 1)
}

const getCursorAngle = (el: HTMLElement, x: number, y: number) => {
    const [cx, cy] = getCenterOfElement(el)
    const dx = x - cx
    const dy = y - cy
    if (dx === 0 && dy === 0) return 0
    const radians = Math.atan2(dy, dx)
    let degrees = radians * (180 / Math.PI) + 90
    if (degrees < 0) degrees += 360
    return degrees
}

const handlePointerMove = (e: PointerEvent) => {
    const card = cardRef.value
    if (!card) return
    const rect = card.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top
    edgeProximity.value = getEdgeProximity(card, x, y)
    cursorAngle.value = getCursorAngle(card, x, y)
}

watch(
    () => [props.animated],
    () => {
        if (!props.animated) return
        const angleStart = 110
        const angleEnd = 465
        sweepActive.value = true
        cursorAngle.value = angleStart

        animateValue({ duration: 500, onUpdate: (v) => (edgeProximity.value = v / 100) })
        animateValue({
            ease: easeInCubic,
            duration: 1500,
            end: 50,
            onUpdate: (v) => {
                cursorAngle.value = (angleEnd - angleStart) * (v / 100) + angleStart
            },
        })
        animateValue({
            ease: easeOutCubic,
            delay: 1500,
            duration: 2250,
            start: 50,
            end: 100,
            onUpdate: (v) => {
                cursorAngle.value = (angleEnd - angleStart) * (v / 100) + angleStart
            },
        })
        animateValue({
            ease: easeInCubic,
            delay: 2500,
            duration: 1500,
            start: 100,
            end: 0,
            onUpdate: (v) => (edgeProximity.value = v / 100),
            onEnd: () => (sweepActive.value = false),
        })
    },
    {
        deep: true,
        immediate: true,
    },
)

const colorSensitivity = computed(() => props.edgeSensitivity + 20)
const isVisible = computed(() => isHovered.value || sweepActive.value)
const borderOpacity = computed(() =>
    isVisible.value
        ? Math.max(0, (edgeProximity.value * 100 - colorSensitivity.value) / (100 - colorSensitivity.value))
        : 0,
)
const glowOpacity = computed(() =>
    isVisible.value ? Math.max(0, (edgeProximity.value * 100 - props.edgeSensitivity) / (100 - props.edgeSensitivity)) : 0,
)

const meshGradients = computed(() => buildMeshGradients(props.colors))
const borderBg = computed(() => meshGradients.value.map((g) => `${g} border-box`))
const fillBg = computed(() => meshGradients.value.map((g) => `${g} padding-box`))
const angleDeg = computed(() => `${cursorAngle.value.toFixed(3)}deg`)
const formattedBorderRadius = computed(() =>
    typeof props.borderRadius === 'number' ? `${props.borderRadius}px` : props.borderRadius,
)

const outerBorderRadius = computed(() => {
    const r = props.borderRadius
    const glow = props.glowRadius
    if (typeof r === 'number') {
        return `${r + glow}px`
    }
    const parts = r.trim().split(/\s+/)
    return parts.map((p) => `calc(${p} + ${glow}px)`).join(' ')
})
</script>

<template>
    <div
        ref="cardRef"
        @pointermove="handlePointerMove"
        @pointerenter="isHovered = true"
        @pointerleave="isHovered = false"
        :class="`relative grid isolate border border-slate-200/60 ${props.className}`"
        :style="{
            background: props.backgroundColor,
            borderRadius: formattedBorderRadius,
            transform: 'translate3d(0, 0, 0.01px)',
            boxShadow: props.cardShadow,
        }"
    >
        <!-- mesh gradient border -->
        <div
            class="-z-[1] absolute inset-0"
            :style="{
                borderRadius: formattedBorderRadius,
                border: '1px solid transparent',
                background: [
                    `linear-gradient(${props.backgroundColor} 0 100%) padding-box`,
                    'linear-gradient(rgb(255 255 255 / 0%) 0% 100%) border-box',
                    ...borderBg,
                ].join(', '),
                opacity: borderOpacity,
                maskImage: `conic-gradient(from ${angleDeg} at center, black ${props.coneSpread}%, transparent ${
                    props.coneSpread + 15
                }%, transparent ${100 - props.coneSpread - 15}%, black ${100 - props.coneSpread}%)`,
                WebkitMaskImage: `conic-gradient(from ${angleDeg} at center, black ${props.coneSpread}%, transparent ${
                    props.coneSpread + 15
                }%, transparent ${100 - props.coneSpread - 15}%, black ${100 - props.coneSpread}%)`,
                transition: isVisible ? 'opacity 0.25s ease-out' : 'opacity 0.75s ease-in-out',
            }"
        />

        <!-- mesh gradient fill -->
        <div
            class="-z-[1] absolute inset-0"
            :style="{
                borderRadius: formattedBorderRadius,
                border: '1px solid transparent',
                background: fillBg.join(', '),
                maskImage: [
                    'linear-gradient(to bottom, black, black)',
                    'radial-gradient(ellipse at 50% 50%, black 40%, transparent 65%)',
                    'radial-gradient(ellipse at 66% 66%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 66% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 66%, black 5%, transparent 40%)',
                    `conic-gradient(from ${angleDeg} at center, transparent 5%, black 15%, black 85%, transparent 95%)`,
                ].join(', '),
                WebkitMaskImage: [
                    'linear-gradient(to bottom, black, black)',
                    'radial-gradient(ellipse at 50% 50%, black 40%, transparent 65%)',
                    'radial-gradient(ellipse at 66% 66%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 66% 33%, black 5%, transparent 40%)',
                    'radial-gradient(ellipse at 33% 66%, black 5%, transparent 40%)',
                    `conic-gradient(from ${angleDeg} at center, transparent 5%, black 15%, black 85%, transparent 95%)`,
                ].join(', '),
                maskComposite: 'subtract, add, add, add, add, add',
                WebkitMaskComposite: 'source-out, source-over, source-over, source-over, source-over, source-over',
                opacity: borderOpacity * props.fillOpacity,
                mixBlendMode: 'soft-light',
                transition: isVisible ? 'opacity 0.25s ease-out' : 'opacity 0.75s ease-in-out',
            }"
        />

        <!-- outer glow: clip-path clips box-shadow to rounded corners (overflow:hidden does NOT clip shadows) -->
        <!-- skipped when disableOuterGlow=true, e.g. when a parent overflow:hidden would clip it -->
        <span
            v-if="!props.disableOuterGlow"
            class="z-[1] absolute pointer-events-none"
            :style="{
                inset: `-${props.glowRadius}px`,
                clipPath: `inset(0 round ${outerBorderRadius})`,
                maskImage: `conic-gradient(from ${angleDeg} at center, black 2.5%, transparent 10%, transparent 90%, black 97.5%)`,
                WebkitMaskImage: `conic-gradient(from ${angleDeg} at center, black 2.5%, transparent 10%, transparent 90%, black 97.5%)`,
                opacity: glowOpacity,
                mixBlendMode: 'plus-lighter',
                transition: isVisible ? 'opacity 0.25s ease-out' : 'opacity 0.75s ease-in-out',
            }"
        >
            <span
                class="absolute"
                :style="{
                    inset: `${props.glowRadius}px`,
                    borderRadius: formattedBorderRadius,
                    boxShadow: buildBoxShadow(props.glowColor, props.glowIntensity),
                }"
            />
        </span>

        <!-- content -->
        <div
            class="z-[1] relative flex flex-col overflow-hidden h-full w-full"
            :style="{ borderRadius: formattedBorderRadius }"
        >
            <slot />
        </div>
    </div>
</template>
